import torch
from pathlib import Path

# Check which checkpoints have the right architecture
good = []
for line in open("ensemble_checkpoints.txt"):
    ckpt = line.strip()
    if not ckpt:
        continue
    try:
        sd = torch.load(ckpt, map_location="cpu", weights_only=True)
        sd = {k.replace("_orig_mod.", ""): v for k, v in sd.items()}
        if "fourier_B" in sd and sd["proj_in.weight"].shape[1] == 88:
            good.append(ckpt)
    except Exception as e:
        pass

print(f"Found {len(good)} compatible checkpoints (out of total)")
with open("ensemble_checkpoints_filtered.txt", "w") as f:
    for g in good:
        f.write(g + "\n")
EOF
